fn module_programs(value: &Value) -> Result<&[(Value, Value)]> {
    let entries = value_map_entries(value)
        .ok_or_else(|| anyhow::anyhow!("program module root must be a map"))?;
    let programs = value_field(entries, "programs")
        .ok_or_else(|| anyhow::anyhow!("program module requires programs"))?;
    let programs = value_map_entries(programs)
        .ok_or_else(|| anyhow::anyhow!("program module programs must be a map"))?;
    if programs.is_empty() {
        bail!("program module programs must not be empty");
    }
    for (name, value) in programs {
        match (name, value) {
            (Value::Text(name), Value::Ref(_)) if !name.is_empty() => {}
